```python
from typing import List

def minValidStrings(words: List[str], target: str) -> int:
    # 建立 Trie 來儲存所有 words 的所有可能前綴
    trie = {}
    for w in words:
        node = trie
        for char in w:
            if char not in node:
                node[char] = {}
            node = node[char]

    n = len(target)
    # dp[i] 表示組成 target[:i] 所需的最少字串數量
    # 初始化為無限大，dp[0] 為 0（空字串需要 0 個）
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] == float('inf'):
            continue

        # 從目前的索引 i 開始，嘗試匹配所有可能的前綴
        node = trie
        for j in range(i, n):
            char = target[j]
            if char not in node:
                break
            node = node[char]
            # 因為任何前綴都是有效的，只要在 Trie 中能走通就代表它是 valid
            dp[j + 1] = min(dp[j + 1], dp[i] + 1)

    return int(dp[n]) if dp[n] != float('inf') else -1
```

