from typing import List

def minValidStrings(words: List[str], target: str) -> int:
    # Build a Trie to store all prefixes of strings in words
    # Actually, since any prefix of a word is valid, 
    # we only need to know if a substring of target starting at i 
    # matches a prefix of ANY word.
    # A string x is valid if it is a prefix of some word in 'words'.

    trie = {}
    for w in words:
        node = trie
        for char in w:
            if char not in node:
                node[char] = {}
            node = node[char]

    n = len(target)
    # dp[i] is the min number of valid strings to form target[:i]
    # Initialize with infinity, dp[0] = 0
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(n):
        if dp[i] == float('inf'):
            continue

        # Try to find all possible valid prefixes starting from target[i]
        node = trie
        for j in range(i, n):
            char = target[j]
            if char in node:
                node = node[char]
                # Every step into the Trie represents a valid prefix
                dp[j + 1] = min(dp[j + 1], dp[i] + 1)
            else:
                break

    return int(dp[n]) if dp[n] != float('inf') else -1
