from collections import Counter

def countPairs(nums: List[int]) -> int:
    def get_variants(n: int) -> set:
        s = list(str(n))
        variants = {tuple(s)}
        # Try all possible swaps of indices i and j
        for i in range(len(s)):
            for j in range(i + 1, len(s)):
                if s[i] != s[j]:
                    s[i], s[j] = s[j], s[i]
                    variants.add(tuple(s))
                    s[i], s[j] = s[j], s[i] # Swap back
        return variants

    count = 0
    # To avoid O(N^2) where N is large, but here N <= 100, 
    # a simple nested loop is efficient enough.
    for i in range(len(nums)):
        variants_i = get_variants(nums[i])
        for j in range(i + 1, len(nums)):
            # If the string representation of nums[j] exists in variants of nums[i]
            if tuple(str(nums[j])) in variants_i:
                count += 1
    return count
