from typing import List

def countPairs(nums: List[int]) -> int:
    def is_almost_equal(x, y):
        s1 = str(x)
        s2 = str(y)
        if len(s1) != len(s2):
            return False
        if s1 == s2:
            return True

        # Check if they have the same digits (multiset equality)
        if sorted(s1) != sorted(s2):
            return False

        # Since lengths are equal and sorted strings match, 
        # we just need to check if swapping two digits in one makes it equal to other.
        # This is equivalent to checking if they differ at most in 2 positions.
        diff_indices = [i for i in range(len(s1)) if s1[i] != s2[i]]
        return len(diff_indices) <= 2

    count = 0
    n = len(nums)
    for i in range(n):
        for j in range(i + 1, n):
            if is_almost_equal(nums[i], nums[j]):
                count += 1
    return count
