import heapq

def minOperations(n: int, m: int):
    if is_prime(m): return -1

    # BFS/Dijkstra to find shortest path in state space
    # State: current value of n. Cost: sum of values taken.
    # Since we want minimum cost and edges have weights (the value itself), 
    # Dijkstra is appropriate.

    pq = [(0, n)] # (total_cost, current_val)
    visited = {n: 0}

    while pq:
        current_cost, curr = heapq.heappop(pq)

        if curr == m:
            return current_cost

        if current_cost > visited.get(curr, float('inf')):
            continue

        s_curr = str(curr)
        for i in range(len(s_curr)):
            digit = int(s_curr[i])
            # Try increasing
            if digit < 9:
                nxt = int(s_curr[:i] + str(digit + 1) + s_curr[i+1:])
                if not is_prime(nxt):
                    new_cost = current_cost + nxt
                    if new_cost < visited.get(nxt, float('inf')):
                        visited[nxt] = new_cost
                        heapq.heappush(pq, (new_cost, nxt))
            # Try decreasing
            if digit > 0:
                nxt = int(s_curr[:i] + str(digit - 1) + s_curr[i+1:])
                # Ensure same number of digits (no leading zeros unless m is 0)
                if len(str(nxt)) == len(m) and not is_prime(nxt):
                    new_cost = current_cost + nxt
                    if new_cost < visited.get(nxt, float('inf')):
                        visited[nxt] = new_cost
                        heapq.heappush(pq, (new_cost, nxt))

    return -1

def is_prime(num):
    if num < 2: return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0: return False
    return True
