def minOperations(n: int, m: int) -> int:
    # Check if n or m is prime initially (or at any point)
    def is_prime(num):
        if num < 2: return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    if is_prime(n) or is_prime(m):
        return -1

    # The cost of a transformation is the sum of all values that n takes throughout the operations.
    # Initial value n is included in the sequence? 
    # Example 1: 10 -> 20 -> 21 -> 22 -> 12
    # Sum = 10 + 20 + 21 + 22 + 12 = 85.
    # This means the sum includes both the starting value and every intermediate step, including m.

    # Dijkstra's algorithm: (current_total_sum, current_val)
    pq = [(n, n)]
    visited = {n: n} # Stores min total cost to reach value u

    while pq:
        current_sum, u = heapq.heappop(pq)

        if u == m:
            return current_sum

        if current_sum > visited.get(u, float('inf')):
            continue

        s = list(str(u))
        for i in range(len(s)):
            digit = int(s[i])

            # Try increasing digit
            if digit < 9:
                temp_s = list(s)
                temp_s[i] = str(digit + 1)
                v = int("".join(temp_s))
                # Ensure v has the same number of digits as original n (no leading zeros unless m is 0)
                if len(str(v)) == len(str(n)):
                    if not is_prime(v):
                        new_sum = current_sum + v
                        if new_sum < visited.get(v, float('inf')):
                            visited[v] = new_sum
                            heapq.heappush(pq, (new_sum, v))

            # Try decreasing digit
            if digit > 0:
                temp_s = list(s)
                temp_s[i] = str(digit - 1)
                v = int("".join(temp_s))
                # Ensure v has the same number of digits as original n
