def getLargestOutlier(nums: List[int]) -> int:
    total_sum = sum(nums)
    # To handle duplicates correctly, we use a frequency map
    counts = {}
    for x in nums:
        counts[x] = counts.get(x, 0) + 1

    # Sort unique numbers to find the largest outlier easily
    unique_nums = sorted(list(set(nums)), reverse=True)

    for x in unique_nums:
        # S = 2Y + X  => Y = (S - X) / 2
        remainder = total_sum - x
        if remainder % 2 == 0:
            y = remainder // 2

            # We need to check if y exists in the array such that we don't 
            # reuse the same index for x and y.
            # Special case: if x == y, there must be at least two occurrences of x.
            if x == y:
                if counts[x] >= 2:
                    return x
            else:
                if y in counts:
                    return x

    return -1 # Should not reach here based on constraints
