```python
from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    # dp[k][i][j] 表示到達 (i, j) 且已使用 k 次能力的最大收益
    # 初始化為負無窮大
    dp = [[[-float('inf')] * n for _ in range(m)] for _ in range(3)]

    # 起點初始化
    start_val = coins[0][0]
    if start_val >= 0:
        dp[0][0][0] = start_val
    else:
        dp[1][0][0] = 0  # 使用一次能力中和負數
        dp[0][0][0] = start_val # 不使用能力，直接扣除

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            current_coin = coins[i][j]
            is_negative = current_coin < 0

            for k in range(3):
                # 從上方或左方過來
                prev_max = -float('inf')
                if i > 0: prev_max = max(prev_max, dp[k][i-1][j])
                if j > 0: prev_max = max(prev_max, dp[k][i][j-1])

                # 情況 1：當前格子是正數（或零）
                if current_coin >= 0:
                    dp[k][i][j] = max(dp[k][i][j], prev_max + current_coin)
                else:
                    # 情況 2：當前格子是負數，不使用能力（直接扣錢）
                    dp[k][i][j] = max(dp[k][i][j], prev_max + current_coin)
                    # 情況 3：當前格子是負數，且還有剩餘次數來中和它
                    if k > 0:
                        prev_max_with_extra = -float('inf')
                        if i > 0: prev_max_with_extra = max(prev_max_with_extra, dp[k-1][i-1][j])
                        if j > 0: prev_max_with_extra = max(prev_max_with_extra, dp[k-1][i][j-1])
                        dp[k][i][j] = max(dp[k][i][j], prev_max_with_extra)

    return max(dp[0][m-1][n-1], dp[1][m-1][n-1], dp[2][m-1][n-1])
```

