```python
from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m = len(coins)
    n = len(coins[0])

    # dp[k][i][j] 表示到達 (i, j) 且使用了 k 次能力的最大收益
    # 使用 -float('inf') 初始化以處理負數收益
    dp = [[[-float('inf')] * n for _ in range(m)] for _ in range(3)]

    # 初始化起始點
    initial_val = coins[0][0]
    if initial_val >= 0:
        dp[0][0][0] = initial_val
    else:
        dp[0][0][0] = initial_val           # 不用能力，被搶走
        dp[1][0][0] = 0                      # 用一次能力，不被搶

    for k in range(3):
        for i in range(m):
            for j in range(n):
                if dp[k][i][j] == -float('inf'):
                    continue

                current_coins = dp[k][i][j]

                # 向右移動或向下移動
                for di, dj in [(0, 1), (1, 0)]:
                    ni, nj = i + di, j + dj
                    if ni < m and nj < n:
                        val = coins[ni][nj]

                        # 選項 1：正常移動（如果是負數就扣錢，正數就加錢）
                        next_val = current_coins + val
                        dp[k][ni][nj] = max(dp[k][ni][nj], next_val)

                        # 選項 2：如果目前格子是負數且還有剩餘能力，可以使用能力中和
                        if val < 0 and k < 2:
                            dp[k+1][ni][nj] = max(dp[k+1][ni][nj], current_coins)

    return max(dp[k][m-1][n-1] for k in range(3))
