from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m = len(coins)
    n = len(coins[0])

    # dp[i][j][k] 表示到達 (i, j) 且使用了 k 次中和能力時的最大金幣數
    # 初始化為極小值，表示該狀態不可達
    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]

    # 起點初始化
    val = coins[0][0]
    if val >= 0:
        dp[0][0][0] = val
    else:
        dp[0][0][1] = 0  # 使用一次中和能力，獲得 0（原本是負數）
        dp[0][0][0] = val # 不使用，獲得負數

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0: continue

            current_val = coins[i][j]
            for k in range(3):
                # 從上方或左方過來的最大值
                prev_max = -float('inf')
                if i > 0: prev_max = max(prev_max, dp[i-1][j])
                if j > 0: prev_max = max(prev_max, dp[i][j-1])

                # 情況 1：當前格子是正數或零 (直接加)
                if current_val >= 0:
                    if k == 0: # 沒用過能力，從之前的 k=0 過來
                        dp[i][j][k] = max(dp[i][j][k], prev_max + current_val if (i>0 or j>0) else -float('inf'))
                    # 注意：如果當前是正數，其實不需要浪費能力去「中和」它，
                    # 但為了邏輯完整，若之前用了 k 次，現在繼續用 k 次也是可行的。
                    # 簡化邏輯：如果是正數，只需從之前的相同 k 過來。
                    if i > 0: dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + current_val)
                    if j > 0: dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + current_val)

                # 情況 2：當前格子是負數 (可以選擇中和或不中和)
                else:
                    # 不中和：從之前的相同 k 過來，加上負數
                    if i > 0: dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + current_val)
                    if j > 0: dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + current_val)

                    # 中和：從之前的 k-1 過來，加上 0 (因為被中和了)
                    if k > 0:
                        if i > 0: dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k-1])
                        if j > 0: dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k-1])

    # 因為起點處理稍微複雜，重新簡化邏輯以確保正確性：
    # 我們可以用一個更清晰的 DP 過度：

    dp = [[[-float('inf')] * 3 for _ in range(n)] for _ in range(m)]

    # 初始化起點
    if coins[0][0] >= 0:
        dp[0][0][0] = coins[0][0]
    else:
        dp[0][0][1] = 0 # 中和
        dp[0][0][0] = coins[0][0] # 不中和

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0: continue
            v = coins[i][j]
            for k in range(3):
                # 基礎：不使用能力（或當前格子不是負數時，本來就不用用）
                res = -float('inf')
                if i > 0: res = max(res, dp[i-1][j][k])
                if j > 0: res = max(res, dp[i][j-1][k])

                if res != -float('inf'):
                    if v >= 0:
                        dp[i][j][k] = max(dp[i][j][k], res + v)
                    else:
                        # 如果是負數，不中和
                        dp[i][j][k] = max(dp[i][j][k], res + v)
                        # 如果有剩餘能力，選擇中和（變成加 0）
                        if k > 0:
                            prev_res = -float('inf')
                            if i > 0: prev_res = max(prev_res, dp[i-1][j][k-1])
                            if j > 0: prev_res = max(prev_res, dp[i][j-1][k-1])
                            dp[i][j][k] = max(dp[i][j][k], prev_res)

    return max(dp[m-1][n-1])
