                    if j > 0: best_prev_prev = max(best_prev_prev, dp[k-1][i][j-1])
                    # Special case for (0,0) is already handled by init, but if path reached here:
                    if i == 0 and j == 0: pass # skip
                    if best_prev_prev != float('-inf'):
                        dp[k][i][j] = max(dp[k][i][j], best_prev_prev + abs(cur))

    return max(dp[0][m-1][n-1], dp[1][m-1][n-1], dp[2][m-1][n-1])
