import math
from typing import List

def maximumAmount(coins: List[List[int]]) -> int:
    m, n = len(coins), len(coins[0])
    # dp[k][i][j] is max coins reaching (i, j) using k neutralizations
    # Use 2D arrays to save space: dp[k][i][j]
    # Since we only need previous row/column, but standard DP for this grid size 
    # is m*n*3. We use a 3D array initialized with -infinity.
    dp = [[[-float('inf')] * n for _ in range(m)] for _ in range(3)]

    for k in range(3):
        val = coins[0][0]
        # If we neutralize the first cell (if it's negative)
        if k > 0 and val < 0:
            dp[k][0][0] = max(dp[k][0][0], 0)
        # Standard gain/loss
        dp[k][0][0] = max(dp[k][0][0], val)

    for i in range(m):
        for j in range(n):
            if i == 0 and j == 0: continue
            val = coins[i][j]
            for k in range(3):
                # Option 1: Don't neutralize current cell (or it's positive)
                prev_max = -float('inf')
                if i > 0: prev_max = max(prev_max, dp[k][i-1][j])
                if j > 0: prev_max = max(prev_max, dp[k][i][j-1])

                if prev_max != -float('inf'):
                    dp[k][i][j] = max(dp[k][i][j], prev_max + val)

                # Option 2: Neutralize current cell (only if it's negative and k > 0)
                if k > 0 and val < 0:
                    prev_max_n = -float('inf')
                    if i > 0: prev_max_n = max(prev_max_n, dp[k-1][i-1][j])
                    if j > 0: prev_max_n = max(prev_max_n, dp[k-1][i][j-1])

                    if prev_max_n != -float('inf'):
                        dp[k][i][j] = max(dp[k][i][j], prev_max_n)

    return int(max(dp[0][m-1][n-1], dp[1][m-1][n-1], dp[2][m-1][n-1]))
