import collections
from math import factorial
from itertools import combinations_with_replacement, permutations

def countGoodIntegers(n: int, k: int) -> int:
    good_multisets = set()
    # Generate all multisets of size n that can form a palindrome (max one odd frequency)
    for combo in combinations_with_replacement(range(10), n):
        counts = collections.Counter(combo)
        odds = sum(1 for c in counts.values() if c % 2 != 0)
        if odds <= 1 and (odds == 0 or odds == 1):
            half_len = n // 2
            mid = -1
            if n % 2 != 0:
                for d, c in counts.items():
                    if c % 2 != 0:
                        mid = d
                        break

            prefix_counts = collections.defaultdict(int)
            for d, c in counts.items():
                if d == mid and n % 2 != 0:
                    prefix_counts[d] = (c - 1) // 2
                else:
                    prefix_counts[d] = c // 2

            prefix_digits = []
            for d, c in prefix_counts.items():
                prefix_digits.extend([d] * c)

            found = False
            if n == 1:
                # For n=1, the multiset is just one digit. Check if it's divisible by k and non-zero.
                for d in combo:
                    if d > 0 and d % k == 0:
                        found = True
                        break
            else:
                # Generate all unique permutations of prefix_digits to check divisibility
                for p in set(permutations(prefix_digits)):
                    if p[0] == 0: continue # No leading zero for n > 1
                    s_str = "".join(map(str, p))
                    mid_str = str(mid) if n % 2 != 0 else ""
                    full_str = s_str + mid_str + s_str[::-1]
                    val = int(full_str)
                    if val > 0 and val % k == 0 and len(full_str) == n:
                        found = True
                        break

            if found:
                ms = []
                for d in sorted(counts.keys()):
                    ms.append((d, counts[d]))
                good_multisets.add(tuple(ms))

    ans = 0
    for ms in good_multisets:
        total_perms = factorial(n)
        counts = collections.defaultdict(int)
        for d, c in ms:
            counts[d] = c
            total_perms //= factorial(c)

        if 0 in counts and n > 1:
            sub_perms = factorial(n - 1)
            counts[0] -= 1
            for d, c in counts.items():
                sub_perms //= factorial(max(0, c))
            total_perms -= sub_perms
        elif n == 1 and 0 in counts:
            # This shouldn't happen based on the 'found' logic but for safety:
            total_perms = 0

        ans += total_perms
    return ans

